//! ↩️ delete-skin leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfSkin;
use crate::artifacts::gltf::schema::mutations::delete_skin::mutation::{validate, GltfDeleteSkinPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{skins_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.delete-skin.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfDeleteSkinInverseOperation { Insert { position: usize, item: GltfSkin }, Delete { index: usize, removed: GltfSkin }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfDeleteSkinInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfDeleteSkinPayload, pub operation: GltfDeleteSkinInverseOperation }
fn operation(payload: &GltfDeleteSkinPayload, base: &GltfSnapshot) -> GltfDeleteSkinInverseOperation { GltfDeleteSkinInverseOperation::Insert { position: payload.index, item: base.document.skins[payload.index].clone() } }
fn touched_paths(payload: &GltfDeleteSkinPayload) -> Vec<String> { vec![format!("document/skins/{}", payload.index)] }
pub fn validate_inverse(inverse: &GltfDeleteSkinInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub fn apply_inverse(inverse: &GltfDeleteSkinInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfDeleteSkinInverseOperation::Insert { position, .. } if *position > after.document.skins.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/skins", "position must be within the collection")), GltfDeleteSkinInverseOperation::Delete { index, .. } if *index >= after.document.skins.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/skins", "index must address an item")), GltfDeleteSkinInverseOperation::Move { index, position } if *index >= after.document.skins.len() || *position >= after.document.skins.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/skins", "indices must address items")), GltfDeleteSkinInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.skins.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.skins.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/skins", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfDeleteSkinInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Skins, &Change::Insert(*position))?; next.document.skins.insert(*position, item.clone());  }, GltfDeleteSkinInverseOperation::Delete { index, .. } => { skins_op(&mut next, GltfTopLevelFamily::Skins, *index, None, None)?;  }, GltfDeleteSkinInverseOperation::Move { index, position } => { skins_op(&mut next, GltfTopLevelFamily::Skins, *index, Some(*position), None)?;  }, GltfDeleteSkinInverseOperation::Reorder { order } => { skins_op(&mut next, GltfTopLevelFamily::Skins, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(inverse: &GltfDeleteSkinInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub fn derive(payload: &GltfDeleteSkinPayload, base: &GltfSnapshot) -> Result<GltfDeleteSkinInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfDeleteSkinInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
